import java.util.*;import com.google.gson.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Source-only proof: real javac temp stores and contiguous loads implement one finite JVM permutation. */
public final class ScalarStackOperationProof implements Opcodes {
 static void need(boolean ok,String why){if(!ok)throw new AssertionError("source_scalar_stack_"+why);}
 static void collect(JsonElement e,List<JsonObject> out){if(e==null||e.isJsonNull())return;if(e.isJsonArray())for(var x:e.getAsJsonArray())collect(x,out);else if(e.isJsonObject()){var o=e.getAsJsonObject();if(o.has("kind")&&o.get("kind").getAsString().equals("source_scalar_stack_permutation"))out.add(o);for(var x:o.entrySet())collect(x.getValue(),out);}}
 static Set<String> names(JsonObject recipe){var rules=new ArrayList<JsonObject>();collect(recipe.get("complete_expression_AST"),rules);var out=new HashSet<String>();for(var rule:rules)for(var x:rule.getAsJsonArray("inputs"))need(out.add(x.getAsJsonObject().get("name").getAsString()),"unique_source_names");return out;}
 static List<AbstractInsnNode> ops(MethodNode m){var out=new ArrayList<AbstractInsnNode>();for(var n:m.instructions)if(n.getOpcode()>=0)out.add(n);return out;}
 static List<Integer> independentOrder(int op,List<Integer> w){int n=w.size();need(n>=1&&n<=4&&w.stream().allMatch(x->x==1||x==2),"finite_input_widths");int top=n-1;int below=n-2;int third=n-3;int fourth=n-4;return switch(op){
  case POP->{need(n==2&&w.get(top)==1&&w.get(below)==1,"explicit_survivor_then_one_category_one_discard");yield List.of(below);}
  case DUP->{need(n==1&&w.get(top)==1,"DUP_category_one");yield List.of(top,top);}
  case SWAP->{need(n==2&&w.get(top)==1&&w.get(below)==1,"SWAP_two_category_one");yield List.of(top,below);}
  case DUP_X1->{need(n==2&&w.get(top)==1&&w.get(below)==1,"DUP_X1_two_category_one");yield List.of(top,below,top);}
  case DUP_X2->{need(w.get(top)==1,"DUP_X2_top_category_one");if(n==2){need(w.get(below)==2,"DUP_X2_wide_below");yield List.of(top,below,top);}need(n==3&&w.get(below)==1&&w.get(third)==1,"DUP_X2_three_category_one");yield List.of(top,third,below,top);}
  case DUP2->{if(n==1){need(w.get(top)==2,"DUP2_one_wide");yield List.of(top,top);}need(n==2&&w.get(top)==1&&w.get(below)==1,"DUP2_two_category_one");yield List.of(below,top,below,top);}
  case DUP2_X1->{if(n==2){need(w.get(top)==2&&w.get(below)==1,"DUP2_X1_wide_top");yield List.of(top,below,top);}need(n==3&&w.get(top)==1&&w.get(below)==1&&w.get(third)==1,"DUP2_X1_three_category_one");yield List.of(below,top,third,below,top);}
  case DUP2_X2->{if(w.get(top)==2){if(n==2){need(w.get(below)==2,"DUP2_X2_two_wide");yield List.of(top,below,top);}need(n==3&&w.get(below)==1&&w.get(third)==1,"DUP2_X2_wide_top_two_narrow");yield List.of(top,third,below,top);}need(w.get(top)==1&&w.get(below)==1,"DUP2_X2_top_narrow_pair");if(n==3){need(w.get(third)==2,"DUP2_X2_wide_below_narrow_pair");yield List.of(below,top,third,below,top);}need(n==4&&w.get(third)==1&&w.get(fourth)==1,"DUP2_X2_four_narrow");yield List.of(below,top,fourth,third,below,top);}
  default->throw new AssertionError("source_scalar_stack_unrecognized_opcode");
 };}
 static final IdentityHashMap<AbstractInsnNode,AbstractInsnNode> lastInsertedAnchors=new IdentityHashMap<>();
 static List<Object> erase(MethodNode m,JsonObject recipe,Set<AbstractInsnNode> erased){var rules=new ArrayList<JsonObject>();collect(recipe.get("complete_expression_AST"),rules);if(rules.size()<2)return eraseOrdered111(m,recipe,erased,true);boolean reversed=true;try{MethodNode probe=new MethodNode(m.access,m.name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(probe);eraseOrdered111(probe,recipe,Collections.newSetFromMap(new IdentityHashMap<AbstractInsnNode,Boolean>()),true);}catch(AssertionError first){if(!String.valueOf(first.getMessage()).equals("source_scalar_stack_contiguous_actual_finite_output_load_order"))throw first;MethodNode probe=new MethodNode(m.access,m.name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(probe);try{eraseOrdered111(probe,recipe,Collections.newSetFromMap(new IdentityHashMap<AbstractInsnNode,Boolean>()),false);}catch(Exception|AssertionError second){second.addSuppressed(first);throw second;}reversed=false;recipe.addProperty("strict_scalar_planning_reverse_order_rejected111",first.getMessage());}var proof=eraseOrdered111(m,recipe,erased,reversed);recipe.addProperty("strict_scalar_verified_plan_order111",reversed?"inner_first_reverse_AST":"saved_AST_order");return proof;}
 static List<Object> eraseOrdered111(MethodNode m,JsonObject recipe,Set<AbstractInsnNode> erased,boolean reversed){lastInsertedAnchors.clear();var rules=new ArrayList<JsonObject>();collect(recipe.get("complete_expression_AST"),rules);if(reversed)Collections.reverse(rules);var proofs=new ArrayList<Object>();var names=new HashSet<String>();
  for(var rule:rules){int op=rule.get("opcode").getAsInt();need(rule.get("only_initialized_inputs").getAsBoolean()&&!rule.get("runtime_control_state").getAsBoolean(),"explicit_initialized_no_dispatch_domain");var inputs=rule.getAsJsonArray("inputs");var widths=new ArrayList<Integer>();var descriptors=new ArrayList<Type>();var vars=new ArrayList<LocalVariableNode>();
   for(var item:inputs){var in=item.getAsJsonObject();String name=in.get("name").getAsString();need(names.add(name),"unique_saved_Java_temp_name");Type t=Type.getType(in.get("descriptor").getAsString());need(t.getSort()!=Type.VOID&&t.getSort()!=Type.METHOD,"valid_actual_descriptor");var matches=m.localVariables.stream().filter(v->v.name.equals(name)).toList();need(matches.size()==1&&matches.get(0).desc.equals(t.getDescriptor()),"actual_javac_LVT_descriptor");vars.add(matches.get(0));descriptors.add(t);widths.add(t.getSize());
   }
   var expected=independentOrder(op,widths);var declared=new ArrayList<Integer>();for(var x:rule.getAsJsonArray("output_input_indexes"))declared.add(x.getAsInt());need(declared.equals(expected),"explicit_finite_output_order");var stores=new ArrayList<AbstractInsnNode>();var allLoads=new ArrayList<VarInsnNode>();var source=ops(m);var positions=new IdentityHashMap<AbstractInsnNode,Integer>();int p=0;for(var n:m.instructions)positions.put(n,p++);
   for(int i=0;i<vars.size();i++){var v=vars.get(i);var t=descriptors.get(i);AbstractInsnNode store=v.start.getPrevious();while(store!=null&&store.getOpcode()<0)store=store.getPrevious();need(store instanceof VarInsnNode s&&s.var==v.index&&s.getOpcode()==t.getOpcode(ISTORE),"one_real_initializer_store_before_LVT");stores.add(store);int start=positions.get(v.start),end=positions.get(v.end);
    for(var n:m.instructions)if(n instanceof VarInsnNode x&&x.var==v.index&&positions.get(n)>=start&&positions.get(n)<end){need(x.getOpcode()==t.getOpcode(ILOAD),"no_temp_mutation_or_category_change");allLoads.add(x);}
    for(var n:m.instructions)if(n instanceof IincInsnNode x&&x.var==v.index&&positions.get(n)>=start&&positions.get(n)<end)need(false,"temp_increment_forbidden");
   }
   for(int i=1;i<stores.size();i++)need(positions.get(stores.get(i-1))<positions.get(stores.get(i)),"actual_input_evaluation_order");allLoads.sort(Comparator.comparingInt(positions::get));need(allLoads.size()==expected.size(),"exact_complete_output_load_count");need(positions.get(stores.get(stores.size()-1))<positions.get(allLoads.get(0)),"all_inputs_evaluated_once_before_consumption");int begin=source.indexOf(allLoads.get(0));
   for(int i=0;i<expected.size();i++){int ix=expected.get(i);var load=allLoads.get(i);need(begin+i<source.size()&&source.get(begin+i)==load&&load.var==vars.get(ix).index&&load.getOpcode()==descriptors.get(ix).getOpcode(ILOAD),"contiguous_actual_finite_output_load_order");}
   var syntheticPermutation=new InsnNode(op);lastInsertedAnchors.put(syntheticPermutation,allLoads.get(0));m.instructions.insertBefore(allLoads.get(0),syntheticPermutation);for(var n:stores){erased.add(n);m.instructions.remove(n);}for(var n:allLoads){erased.add(n);m.instructions.remove(n);}for(var v:vars)m.localVariables.remove(v);m.maxStack+=16;
   proofs.add(Map.of("opcode",op,"input_descriptors",descriptors.stream().map(Type::getDescriptor).toList(),"output_input_indexes",expected,"real_javac_stores",stores.size(),"real_javac_loads",allLoads.size(),"source_only",true,"original_Code_frames_or_incoming_states_used",false));
  }
  return proofs;
 }
}
